# VULNERABLE: predictable IDs + no ownership check.
counter = 0
def new_session():
    global counter
    counter += 1
    return f"session_{counter}"            # guessable

def load_memory(session_id):
    return db.get(session_id)              # anyone who knows the ID can read it


# SECURE: unguessable IDs + ownership enforced in code.
import secrets

def new_session(user_id):
    sid = secrets.token_urlsafe(32)        # 256 bits of randomness, not guessable
    db.set_owner(sid, user_id)
    return sid

def load_memory(session_id, *, current_user_id):
    if db.owner_of(session_id) != current_user_id:
        raise PermissionError("Not your session")   # authorization check
    return db.get(session_id)
